"""Revise interpretation using additional starts, local projections and CCX pairs."""
from pathlib import Path
from copy import deepcopy
import json,math
from docx import Document
from docx.shared import Cm,Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from build_v17 import write
from build_corrected_manuscript import paragraph,table
ROOT=Path(__file__).resolve().parents[1];OLD=ROOT/'revision_19_2026-11-01';OUT=ROOT/'revision_20_2026-11-01'
def f(x):return '—' if x is None else f'{x:.3g}'
def main():
    a=json.loads((OUT/'analysis_v20.json').read_text());selected=a['fine_selected'];attempts=a['fine_attempts'];loc=a['local_design'];cx=a['calculix']
    def fit(design,restricted=False):return next(r for r in selected if r['design']==design and r['restricted']==restricted)
    def ld(design,offset=True,step=1.):return next(r for r in loc['results'] if r['design']==design and r['offset_estimated']==offset and r['step_factor']==step)
    d=Document(OLD/'MMT_manuscript_Q1_revision_v19_clean.docx');changes=[]
    def patch(prefix,new):
        p=next(p for p in d.paragraphs if p.text.startswith(prefix));changes.append(dict(before=p.text,after=new));write(p,new);return p
    p=next(p for p in d.paragraphs if p.text.startswith('Inferring gear microgeometry'))
    text=p.text.replace('Inverse estimates shift with reference resolution despite small transmission residuals.','Small transmission residuals do not certify unique recovery or a preferred sampling design.')
    text=text.replace('A 5% gain perturbation raises deeper-case median scaled error from 0.0916 to 1.86 across 200 paired realizations.','For one virtual truth, five starts yield repeatable fine-reference fits; the mixed design increases profile error despite better local conditioning.')
    assert len(text.split())<=180;patch('Inferring gear microgeometry',text)
    p=next(p for p in d.paragraphs if p.text.startswith('Bounds are C') and '0.005' in p.text)
    bounds_prefix=p.text[:60]
    text=p.text
    begin=text.index('The 0.08 mm reference uses starts')
    text=text[:begin]+('The 0.08 mm reference uses starts (0.018,0.72,0.008,0.45) and (0.025,0.82,0.014,0.60). At 0.04 mm, the original coarse-initialized fit is supplemented by those same two starts and (0.012,0.60,0.003,0.20) and (0.032,0.86,0.020,0.65): five full starts per design. Restricted C_d=0 fits fix s_d=0.50 and use three starts per fine-grid design, including the preceding full-fit estimate projected onto its two free addendum coordinates. The analytical control uses the same observations, bounds and two original starts, its analytic tangent and a 600-evaluation budget. All 30 cycle-inverse attempts are retained, including '+str(a['failed_additional'])+' unsuccessful additional attempts (Tables S35 and S37). Equal observation count is enforced; equal computational cost, global minimization and calibrated likelihood intervals are not claimed.')
    patch(bounds_prefix,text)
    p=next(p for p in d.paragraphs if p.text.startswith('On the 18 former omissions specifically'))
    patch('On the 18 former omissions specifically','On the 18 former omissions specifically, combined-profile refinement changes the centred observable by 0.0389 µm RMS, compared with the historical 0.18 µm differential-signal scale. This is a declared scale comparison between two grids, not an established refinement criterion or an estimate of continuum error. The corresponding uncentred approach change is 0.226 µm RMS. No third full-cycle grid or convergence order is established, and these calculations do not resolve the separate nanometre-scale structural effect.')
    cap=next(p for p in d.paragraphs if p.text.startswith('Table 10 Equal-count'))
    patch('Table 10 Equal-count',cap.text.replace('The minimum final objective selects a full and a restricted fit within each model/design; selection includes nonconverged attempts.','The minimum final objective selects each full/restricted fit. The fine reference uses five full and three restricted starts per design; the coarser reference uses two/one and the analytical control two/two. Selection retains unsuccessful attempts.'))
    t=next(t for t in d.tables if t.cell(0,0).text=='Model / design')
    expected=[]
    for row in t.rows[1:]:
        label=row.cells[0].text
        if label.startswith('Moving 0.04'):
            des='interior' if label.endswith('Interior') else 'with_transitions';b=fit(des);n=fit(des,True);th=b['theta']
            values=[label,f(th[0]*1000)+' / '+f(th[1]),f(th[2]*1000)+' / '+f(th[3]),f(b['residual_RMS_um']),f(n['residual_RMS_um']),f(b['full_cycle_prediction_RMS_um']),'C' if b['success'] else 'L']
            for cell,value in zip(row.cells,values):
                p=cell.paragraphs[0];write(p,value)
                for r in p.runs:r.font.size=Pt(9)
        expected.append([c.text for c in row.cells])
    bi,bm=fit('interior'),fit('with_transitions')
    patch('At the 0.04 mm reference spacing','At the 0.04 mm reference spacing, the selected interior and mixed fits estimate C_d='+f(bi['theta'][2]*1000)+' and '+f(bm['theta'][2]*1000)+' µm, and s_d='+f(bi['theta'][3])+' and '+f(bm['theta'][3])+', against the generating 10 µm and 0.50. Normal-relief-field RMS errors are '+f(bi['normal_relief_RMS_um'])+' and '+f(bm['normal_relief_RMS_um'])+' µm. Including the former omissions therefore does not improve this full-field point-error metric in the tested case. Its interpretation differs from the training residual and the 90-station prediction check; no universal sampling preference follows from one deterministic truth.')
    anchor=next(p for p in d.paragraphs if p.text.startswith('The fitted profiles and residuals must'))
    def insert(text):
        p=paragraph(d,'');write(p,text);anchor._p.addprevious(p._p);return p
    ranges=[]
    for des in ['interior','with_transitions']:
        rr=[r for r in attempts if r['design']==des and not r['restricted'] and 'theta' in r]
        ranges.append(dict(design=des,n=len(rr),success=sum(r.get('success',False) for r in rr),depth_span_um=1000*(max(r['theta'][2] for r in rr)-min(r['theta'][2] for r in rr)),start_span=max(r['theta'][3] for r in rr)-min(r['theta'][3] for r in rr)))
    insert('The additional fine-reference initialization checks separate a tested-start effect from a resolution comparison. Among the five full attempts per design, '+str(ranges[0]['success'])+' interior and '+str(ranges[1]['success'])+' mixed attempts report convergence. Returned depth spans are '+f(ranges[0]['depth_span_um'])+' and '+f(ranges[1]['depth_span_um'])+' µm and start-coordinate spans '+f(ranges[0]['start_span'])+' and '+f(ranges[1]['start_span'])+', respectively (Table S37). Both original fixed starts are now common to the coarse and fine references. These finite checks describe algorithmic repeatability; they do not certify physical accuracy, uniqueness or a global optimum.')
    li,lm=ld('interior'),ld('with_transitions')
    sig={}
    for des in ['interior','with_transitions']:
        sig[des]={r['component']:r['design_centered_RMS_um'] for r in loc['generator_contrasts'] if r['design']==des}
    insert('A local diagnostic tests the proposed addendum/offset explanations without inferring a cause from the two profile errors alone. Central finite differences at the known truth use the declared parameter scales, the 0.1 µm objective normalization, and the original difference steps and their halves. The two dedendum columns are projected off the addendum columns and, when estimated, a constant offset. With an estimated offset, their smallest singular values are '+f(li['projected_dedendum_singular_values'][-1])+' and '+f(lm['projected_dedendum_singular_values'][-1])+' for interior and mixed designs; the corresponding log determinants of the projected tangent Gram matrices are '+f(li['logdet_dedendum_information'])+' and '+f(lm['logdet_dedendum_information'])+'. Fixing the offset is a hypothetical calibration control, not an available measured datum (Table S38).')
    insert('The full-geometry generator gives design-centred addendum/dedendum RMS contrasts of '+f(sig['interior']['addendum'])+'/'+f(sig['interior']['dedendum'])+' µm for the interior design and '+f(sig['with_transitions']['addendum'])+'/'+f(sig['with_transitions']['dedendum'])+' µm for the mixed design. These component contrasts and scaled local tangents are distinct diagnostics, not a variance decomposition. Projecting the deterministic reference-minus-generator discrepancy through the same tangent predicts unbounded local (C_d,s_d) values ('+f(li['linear_dedendum_point'][0]*1000)+' µm, '+f(li['linear_dedendum_point'][1])+') and ('+f(lm['linear_dedendum_point'][0]*1000)+' µm, '+f(lm['linear_dedendum_point'][1])+'). This tests how design weights the declared discrepancy. It does not isolate contact activation as a causal mechanism or predict bounded nonlinear performance under added noise. Difference-step sensitivity and the fixed-offset control are retained in Table S38.')
    insert('Both reported local criteria—the smallest projected singular value and the Gram-matrix log determinant—favour the mixed design with either difference step and either offset treatment. Estimating the offset reduces its log determinant more strongly, but does not reverse that ordering. The addendum/dedendum contrast ratio is '+f(sig['interior']['addendum']/sig['interior']['dedendum'])+' for interior and '+f(sig['with_transitions']['addendum']/sig['with_transitions']['dedendum'])+' for mixed observations. Thus these diagnostics do not support a simple addendum-dilution explanation for the larger mixed-design profile error. The local discrepancy projection instead reproduces the direction and approximate magnitude of the dedendum bias, consistent with design-dependent propagation of model discrepancy. This remains a local explanation of the tested deterministic case, not an exclusive causal attribution or a noise-robust design result.')
    entry=next(c for c in cx['comparisons'] if c['folder']=='calculix_cycle_crosscheck' and c['phase']==.225);interior=next(c for c in cx['comparisons'] if c['folder']=='calculix_cycle_crosscheck' and c['phase']==.5);offset=cx['offset_free_two_phase'];assert offset
    maxpen=max(max(0,-r['reprojected_minimum_gap_um']) for r in cx['results'])
    patch('Independent mechanical checks use CalculiX','Independent mechanical checks use CalculiX 2.23 [48]. The preceding six nominal controls (Table S34) differ from the bilateral entry approach by 0.100 and 0.0635 µm at two matched resolutions. These absolute differences are not negligible relative to the 0.243 µm full-cycle isolated RMS scale, but they are not errors of the isolated contrast. Additional paired addendum-only/combined profiles directly test that contrast (Table S39). At f=0.225, index 27 inside the former omitted block, the same assumed contours and body meshes as the fine cycle give '+f(entry['calculix_contrast_um'])+' µm with hard mortar and '+f(entry['own_contrast_um'])+' µm with the bilateral implementation, a signed difference of '+f(entry['difference_um'])+' µm. At f=0.50 the contrasts are '+f(interior['calculix_contrast_um'])+' and '+f(interior['own_contrast_um'])+' µm. Subtracting the two phases cancels a constant offset per profile and gives '+f(offset['calculix_two_phase_contrast_um'])+' versus '+f(offset['own_two_phase_contrast_um'])+' µm, a difference of '+f(offset['difference_um'])+' µm. These are pointwise/two-phase contrasts, not full-cycle RMS values.')
    p=next(p for p in d.paragraphs if p.text.startswith('Independent mechanical checks use CalculiX'))
    follow=paragraph(d,'CalculiX and the bilateral model share geometry and Gmsh meshes, while contact enforcement, FE assembly and nonlinear kinematics differ. Selected entry controls at two surface/bulk settings and a same-grid continuation check are retained separately; the preceding nominal penalty alternatives remain in Table S34. Across the new accepted cases, the maximum reprojection-based nodal penetration is '+f(maxpen)+' µm; weak mortar enforcement therefore does not provide the bilateral implementation’s strict nodal nonpenetration tolerance. Equilibrium and plane-strain checks are archived with these geometric diagnostics. Agreement of a differential contrast can reflect cancellation of common discrepancy and does not certify physical or continuum accuracy. The several-nanometre contrast differences also do not certify the separate 0.4–2.1 nm structural-removal control. Extruded wedges with constrained out-of-plane displacement reproduce plane strain, not three-dimensional face-width effects. No independent complete-cycle or inverse-profile validation is claimed.');p._p.addnext(follow._p)
    patch('The cross-operator experiments distinguish','The fixed-contact theorem and the updated-contact experiments concern different hypotheses. Propositions 1–2 guarantee invariance when nonnegative relief changes only gaps outside the loaded support while contact coordinates, normals and compliance remain fixed. Updating contact geometry or elastic stiffness removes that guarantee; violating a sufficient condition does not prove sensitivity, identifiability or the location where information must appear. The historical fixed-normal FE data in Section 4.5 admit compensating profiles. The separate generator and approximate inverse in Section 4.9 yield near-truth fine-reference point estimates for this virtual case, with reproducibility across the tested starts, but with design-dependent profile errors and remaining discretization/discrepancy dependence. This is compatible with the theorem, rather than a converse inferred from it. Several model features change together, so the comparisons do not isolate moving normals as the cause of improved numerical recovery. A small residual remains distinct from unique or physically validated geometry.')
    p=next(p for p in d.paragraphs if p.text.startswith('The results suggest three practical rules'))
    patch('The results suggest three practical rules',p.text.replace('Third, report','The equal-count example further shows that better nuisance-profiled local conditioning can coexist with larger profile error when discrepancy is propagated through the inverse. Third, report'))
    p=next(p for p in d.paragraphs if p.text.startswith('The stress controls extend'))
    patch('The stress controls extend',p.text.replace('The updated-contact experiment additionally provides a complete discrete cycle and equal-count transition controls, while leaving continuum-converged and physically measured parameter recovery unestablished.','Five-start fine-reference checks give repeatable point fits to one virtual truth. The mixed design has better projected local criteria but larger full-profile error; local discrepancy propagation approximates the dedendum bias. Paired CalculiX tests corroborate selected differential contrasts without establishing complete-cycle or physical inverse validation.'))
    p=next(p for p in d.paragraphs if p.text.startswith('Limitations and outlook.'))
    patch('Limitations and outlook.',p.text.replace('Selected independent-solver checks validate neither the complete cycle nor physical relief recovery.','Paired independent-solver checks now assess selected relief contrasts, including one formerly omitted station; they validate neither the complete cycle nor physical relief recovery.').replace('The current archive also remains without a repository DOI.','The moving-contact cycle inversions remain deterministic: no σ=0.1 µm noisy-refitting campaign, third full-cycle generator grid, or calibration of the Δχ²=3.841 profile threshold is supplied. The gain-effect bootstrap concerns a simulation-summary statistic and does not calibrate parameter-profile coverage. A global identifiability map, support-sweeping load optimization and equivalence testing remain unperformed; no global optimum or equivalence is claimed. The current archive remains without a repository DOI.'))
    p=next(p for p in d.paragraphs if p.text.startswith('As a screening diagnostic,'))
    patch('As a screening diagnostic,',p.text.replace('4/200 IID fits cross the screen.','4/200 IID fits cross the screen. The latter is a 2.0% empirical false-alarm rate under this pure-IID generating control and the declared finite fitting procedure, not a universal calibrated rate (Table S29).'))
    patch('Data availability.','Data availability. MMT_reproducibility_v20.zip supplies the additional fine-reference starts, local finite-difference/projection diagnostics, raw paired CalculiX inputs/outputs, numerical audits and construction files. It includes the unchanged version-19 evidence archive with the 720 cycle observations, six closure controls, original inverse controls and earlier stress campaigns. All attempted fits and failed solver runs are retained; large regenerable compliance caches and solver binaries are excluded with explicit recipes. The public version-13 baseline at https://github.com/romusan/gears-inversion-reproducibility/tree/manuscript-v13 does not include subsequent controls. No current-version repository DOI is assigned.')
    evidence=next(t for t in d.tables if t.cell(0,0).text=='Evidence')
    for row in evidence.rows:
        if row.cells[0].text=='Full-cycle bilateral contact':
            write(row.cells[2].paragraphs[0],'Complete virtual cycles, five fine-reference starts per design, local nuisance/offset diagnostics and selected independent paired relief contrasts')
            for r in row.cells[2].paragraphs[0].runs:r.font.size=Pt(9)
    d.core_properties.version='20';d.save(OUT/'MMT_manuscript_Q1_revision_v20_clean.docx')
    s=Document(OLD/'MMT_supplementary_Q1_revision_v19.docx')
    p=next(p for p in s.paragraphs if p.text.startswith('Supplementary Table S35 '));write(p,p.text.replace('Every new inverse attempt, with termination flags.','Original cycle-inverse attempts, retained unchanged. The fine-reference extension is in Table S37.'))
    # Explicit empirical rates, preserving every preceding numerical cell.
    screen=s.tables[28];screen.add_column(Cm(1.4))
    for i,row in enumerate(screen.rows):
        cell=row.cells[-1];cell._tc.remove(cell._tc.tcPr);cell._tc.insert(0,deepcopy(row.cells[-2]._tc.tcPr));cell.width=Cm(1.4)
        txt='Flag %' if i==0 else ('—' if row.cells[6].text=='—' else f'{100*int(row.cells[6].text)/int(row.cells[2].text):.1f}')
        p=cell.paragraphs[0];write(p,txt);p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        for r in p.runs:r.font.size=Pt(9);r.bold=i==0
    paragraph(s,'Additional initialization design and independent contrast checks','Heading 1')
    def cap(text):
        p=paragraph(s,'');write(p,text);p.paragraph_format.keep_with_next=True;p.paragraph_format.keep_together=True
    cap('Supplementary Table S37 All fine-reference attempts at surface step 0.04 mm and bulk parameter 0.50 mm. P is the preceding coarse-initialized full attempt; R0 its restricted counterpart. S1–S4 use fixed starts (0.018,0.72,0.008,0.45), (0.025,0.82,0.014,0.60), (0.012,0.60,0.003,0.20) and (0.032,0.86,0.020,0.65). R5 starts from the preceding fine full estimate and R6 from S2, projected onto the two addendum coordinates with C_d=0 and s_d=0.50. Each design has five full and three restricted attempts, with the same bounds, 30 observations and 25-evaluation budget. P-field is normal-relief-field RMS error over 1001 uniform involute coordinates; C/L indicate solver success/unsuccessful termination and do not certify correctness. All attempts are retained.')
    rows=[]
    rank={'P':0,'S1':1,'S2':2,'S3':3,'S4':4,'R0':5,'R5':6,'R6':7}
    for r in sorted(attempts,key=lambda r:(r['design']!='interior',rank[r['start_id']])):
        rows.append(['Interior' if r['design']=='interior' else 'Mixed',r['start_id'],'Null' if r['restricted'] else 'Full',', '.join(f(v) for v in r['theta']) if 'theta' in r else 'Error',f(r.get('residual_RMS_um')),f(r.get('normal_relief_RMS_um')),'C' if r.get('success') else 'L'])
    table(s,['Design','Start','Fit','θ (mm, –, mm, –)','RMS µm','P-field µm','Flag'],rows,[2,1.2,1,5,1.6,1.6,1])
    paragraph(s,'All 16 fine-reference attempts combine four preserved controls with 12 additional attempts. Selection uses training objective, not error against the known truth. Raw starts, complete predictions, termination messages and forward convergence diagnostics are archived; reported wall times include task scheduling and are not computational-efficiency comparisons.')
    cap('Supplementary Table S38 Local design diagnostics at the known truth using the unchanged nominal-elasticity inverse. Central differences use the declared native steps and their halves; columns are scaled by (0.020,0.20,0.010,0.30) and divided by 0.1 µm. The dedendum columns are projected orthogonally off the addendum columns and, for estimated offset, the constant column. s_min and logdet concern that two-column projected tangent/Gram matrix. The unbounded local point comes from least-squares projection of the deterministic reference-minus-generator discrepancy, not noisy refitting, a bounded estimate or a confidence interval. A fixed offset is a hypothetical calibrated control. Values may lie outside the nonlinear fit bounds.')
    rr=[]
    for r in loc['results']:
        th=r['linear_dedendum_point'];rr.append(['Interior' if r['design']=='interior' else 'Mixed',f(r['step_factor']),'Estimated' if r['offset_estimated'] else 'Fixed',f(r['projected_dedendum_singular_values'][-1]),f(r['logdet_dedendum_information']),f(th[0]*1000),f(th[1])])
    table(s,['Design','Step ×','Offset','Min. s','logdet','Local depth µm','Local start'],rr,[2,1,2,1.5,2,2.4,2])
    paragraph(s,'The addendum tangent fraction is defined using the same declared scaled columns, so it is scale dependent and is not a physical variance fraction. Full matrices, finite perturbation predictions, original objective normalization and all per-phase diagnostics are archived in experiments/local_tangent_factor*.npz and local_forward_v20.json. The design-centred component contrasts in the main text use the separately reassembled full-geometry generator; they are not the nominal-elasticity tangent.')
    cap('Supplementary Table S39 Independent paired relief contrasts at 300 Nm. Δ is combined-minus-addendum approach at one phase, in µm, without phase centring. Cycle mesh means the same contours, complete-five-tooth near-field mesh and continuous pose as the v19 generator; phase-local mesh matches the preceding selected-phase study. Hard mortar uses its documented incremental pairing. The initial fraction is the normalized first load increment, with automatic cutback allowed; all final states target 300 Nm after the prescribed initial rotation. These are selected pointwise contrasts, not full-cycle RMS or physical validation. All original inputs, outputs, termination and geometric checks are archived.')
    rr=[]
    for r in cx['comparisons']:
        rr.append([f(r['phase']),f(r['step'])+'/'+f(r['h']),'Cycle' if r['folder']=='calculix_cycle_crosscheck' else 'Phase-local',f(r['initial_increment']),f(r['own_contrast_um']),f(r['calculix_contrast_um']),f(r['difference_um'])])
    table(s,['Phase f','Surface / h mm','Mesh','Initial fraction','Own Δ µm','CCX Δ µm','CCX−own µm'],rr,[1.4,2.3,2.2,1.7,2,2,2.3])
    paragraph(s,'For the matched cycle meshes, (combined_0.225−combined_0.50)−(addendum_0.225−addendum_0.50) cancels a constant offset per profile. Its values are '+f(offset['own_two_phase_contrast_um'])+' µm (bilateral) and '+f(offset['calculix_two_phase_contrast_um'])+' µm (CalculiX), difference '+f(offset['difference_um'])+' µm. It does not eliminate gain or phase error and is not a cycle RMS.')
    continuation=cx['continuation_control'];assert continuation
    paragraph(s,'The fine phase-local addendum run with small initial increments exceeded the declared 600-second wall limit. Its paired combined run was interrupted before final equilibrium; neither is treated as a converged result. Both profiles were retried with a full initial load fraction, and a same-grid 0.02/0.35 mm pair controls this continuation change. The slow/full-increment isolated contrasts are '+f(continuation['slow_contrast_um'])+'/'+f(continuation['fast_contrast_um'])+' µm, difference '+f(continuation['difference_um'])+' µm. Original partial inputs/outputs, interruption reasons and all accepted reruns are retained. The initial rotations are 0.00084 rad for entry and 0.00079 rad for the matched-cycle interior pair; rotations are then released under torque control.')
    paragraph(s,'Accepted new final states: '+str(len(cx['results']))+'; failed or unfinished inputs retained: '+str(len(cx['failed_or_unfinished']))+'. Maximum relative torque/force/moment residuals are '+ '/'.join(f(max(r[k] for r in cx['results'])) for k in ['torque_relative_error','force_balance_relative','moment_balance_relative'])+'. Maximum plane-strain kinematic discrepancy is '+f(max(r['plane_strain_error_um'] for r in cx['results']))+' µm; maximum two-direction reprojected nodal penetration is '+f(maxpen)+' µm; maximum polygon overlap is '+f(max(r['polygon_overlap_area_mm2'] for r in cx['results']))+' mm². Active/inactive COPEN outputs and reprojected geometry are distinct checks; weak mortar contact does not enforce pointwise nonpenetration to the bilateral solver tolerance. Shared geometry/mesh and differing nonlinear kinematics limit the meaning of cross-code agreement.')
    meshcheck=json.loads((OUT/'audit_shared_mesh_v20.json').read_text())
    paragraph(s,'Mesh-transfer verification reconstructs linear plane-strain stiffness from the exported CalculiX nodes/elements for the two modified pinions and nominal wheel at f=0.225. Eight condensed-compliance columns per body agree with the archived generator columns to at most '+f(max(r['compliance_column_relative_error'] for r in meshcheck['results']))+' relative maximum-entry error. This verifies the shared mesh/compliance transfer for the sampled columns, independently of contact solving; it is not validation of nonlinear contact or physical geometry.')
    s.core_properties.version='20';s.save(OUT/'MMT_supplementary_Q1_revision_v20.docx')
    h=Document(OLD/'Highlights_v19.docx')
    for p in h.paragraphs:
        if p.text.startswith('• Equal-count designs'):write(p,'• Better local conditioning can coexist with larger profile error')
    h.core_properties.version='20';h.save(OUT/'Highlights_v20.docx')
    c=Document(OLD/'Cover_letter_MMT_v19.docx')
    for p in c.paragraphs:
        if p.text.startswith('The submission includes'):
            write(p,'The submission includes supplementary Tables S1–S39, Highlights and a version-20 reproducibility archive. The complete numerical cycle retains 720 observations and six closure controls. Additional fine-reference initialization checks, local design/offset diagnostics and independent paired relief contrasts address the stability and interpretation of the inverse results. Earlier stress campaigns are unchanged. No measured-relief reconstruction, calibrated profile coverage, global optimum or continuum-converged inverse is claimed. No current-version repository DOI is assigned.')
    c.core_properties.version='20';c.save(OUT/'Cover_letter_MMT_v20.docx')
    (OUT/'editorial_changes_v20.json').write_text(json.dumps(changes,ensure_ascii=False,indent=2));(OUT/'table10_expected_v20.json').write_text(json.dumps(expected,indent=2));(OUT/'start_ranges_v20.json').write_text(json.dumps(ranges,indent=2));print('v20 authored',len(text.split()),'methods words')
if __name__=='__main__':main()
